const budget = AbortSignal.timeout(2_000);
const signal = AbortSignal.any([callerSignal, budget]);

try {
    await fetch(url, { signal });
} catch (e) {
    if (callerSignal.aborted) throw e;                 // caller asked to stop
    if (budget.aborted) timeout();                     // our own deadline
}

